def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my_last, opp_last = history[-1]

    # Calculate global and recent stats
    opp_defects_total = sum(1 for m, o in history if o == 'D')
    opp_coops_total = n - opp_defects_total

    # Early game: establish cooperation, simple TFT
    if n < 5:
        return 'C' if opp_last == 'C' else 'D'

    # Late game endgame logic
    if n >= 96:
        # If opponent has been consistently cooperative, exploit them at the very end
        if opp_defects_total <= 2:
            return 'D'
        # If opponent is mixed or defective, stick to standard rules based on last move
        return 'C' if opp_last == 'C' else 'D'

    # Analyze recent behavior (last 10 rounds) to detect patterns vs noise
    recent_window = min(n, 10)
    recent_history = history[-recent_window:]
    recent_opp_defects = sum(1 for m, o in recent_history if o == 'D')
    recent_my_defects = sum(1 for m, o in recent_history if m == 'D')

    # Forgiveness Mechanism: 
    # If we are currently in a cycle of mutual defection but opponent has mostly cooperated historically,
    # try to break out by cooperating.
    if my_last == 'D' and opp_last == 'D':
        # Check if they've been good recently despite this last D
        if recent_opp_defects <= 2 and opp_coops_total > 3 * n / 4:
            # Small chance to forgive to restart CC loop
            if rng.random() < 0.1:
                return 'C'

    # Tit-for-Tat Core with Noise Handling
    if opp_last == 'D':
        # Immediate retaliation unless it looks like a single blip in an otherwise cooperative match
        # "Single blip": Opponent defected once in last 10, but cooperated 8+ times
        if recent_opp_defects == 1 and recent_window >= 10:
             # If I was C when they D'd, they exploited me. Retaliate.
             # But if I also D'd recently, maybe stay D?
             if my_last == 'C':
                 return 'D'
             else:
                 # We were both defecting. If their total defect rate is low, consider forgiveness probability
                 if opp_defects_total / n < 0.1:
                     if rng.random() < 0.15:
                         return 'C'
                 return 'D'
        elif recent_opp_defects <= 2 and opp_defects_total / n < 0.15:
            # Very forgiving against high-cooperators who slip up rarely
            if rng.random() < 0.2:
                return 'C'
            return 'D'
        else:
            # Standard retaliation for frequent defectors
            return 'D'

    # Opponent Cooperated Last Round
    else:
        # If we were Defecting, switch back to Cooperation to reward them
        if my_last == 'D':
            return 'C'

        # We were both Cooperating. Maintain CC.
        # Optional: Occasional probe if they are VERY predictable (always C so far)
        if opp_defects_total == 0 and n > 20:
            if rng.random() < 0.05:
                return 'D'

        return 'C'
